#!/bin/bash
# batch B1: generated by scripts/make_batch.py from tracks/kb/claims_tracks/decisions/B1.tsv; do not edit by hand
cd /data/haiyangw/nrpic/wt/kb || exit 2
fail=0
test -n "${NRPIC_RUN_DIR:-}" || { echo 'not inside nrpic-run'; exit 2; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py snapshot tracks/kb/claims_tracks/decisions/B1.tsv > "$NRPIC_RUN_DIR/before.json" || fail=1
/usr/bin/python3 -I kb/bin/kb claim verify 203 --by kb-claims_tracks --evidence '2111.09163v2 abstract (L68-80), L76: the new energy density holds only propagating modes on the Newtonian constant-time hypersurface at second order. The numbers the machine missed (68, 80) are the note'"'"'s line range, not quoted values.' || { echo FAILED 203; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 209 --by kb-claims_tracks --evidence '2111.09163v2 conclusions (L629-660), L647: the Newtonian constant-time hypersurface could be useful for purely oscillating second-order gravitational waves. Missing numbers 629, 660 are the note'"'"'s line range.' || { echo FAILED 209; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 219 --by kb-claims_tracks --evidence '2610.23218v1: the abstract is one line, L41 (the note'"'"'s 39-41 span the abstract environment): lapse conditions must be adapted to the cosmological setting, the Gamma-driver fails at shell focusing, shift damping depends on the resolution of the focusing region; L51: shell crossing and focusing make fluid simulations fail.' --locator '2610.23218v1:main.tex:L41; 2610.23218v1:main.tex:L51' || { echo FAILED 219; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 226 --by kb-claims_tracks --evidence '2010.12584v2: abstract L143 (one line): convergence of the LPT series at shell crossing established for random 3D initial data, convergence studies up to 40th order; L404-407: median eigenvalues 0.41 and 0.65 at first shell crossing (fairly ellipsoidal), quasi one-dimensional collapse rarely the source.' --locator '2010.12584v2:nLPT-arxiv-v2.tex:L143; 2010.12584v2:nLPT-arxiv-v2.tex:L404-407' || { echo FAILED 226; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/annotate.py annotate tracks/kb/claims_tracks/decisions/B1_annot.tsv || { echo FAILED annotate; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim check --id 203 209 --by kb-claims_tracks || { echo FAILED check; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py rows tracks/kb/claims_tracks/decisions/B1.tsv "$NRPIC_RUN_DIR/before.json" "$NRPIC_RUN_ID" > "$NRPIC_RUN_DIR/ledger_rows.tsv" || fail=1
exit $fail
